// User-supplied HTTPS cover hosts are intentionally not sent through a fixed remote-image optimizer.
// eslint-disable-next-line @next/next/no-img-element
export function BookCover({book,priority=false}:{book:Pick<Book,'title'|'coverUrl'>;priority?:boolean}){const [failedUrl,setFailedUrl]=useState<string|null>(null);return <div className="muse-book-cover">{book.coverUrl&&validCoverUrl(book.coverUrl)&&failedUrl!==book.coverUrl?<img src={book.coverUrl} alt="" width={300} height={450} loading={priority?'eager':'lazy'} decoding="async" onError={()=>setFailedUrl(book.coverUrl??null)}/>:<div aria-hidden="true"><span>✦</span><strong>{book.title}</strong></div>}</div>;}
